const fs = require('fs');
const KANTOOR_PATH = '/data/shared/kantoor.json';

// LET OP bij uitbreiden: deze node geeft de velden expliciet terug. Een veld dat
// hier niet in staat, komt wél op schijf maar nooit terug in het scherm — en de
// eerstvolgende opslag maakt het dan leeg. Elk nieuw veld moet hier én in
// 'Save Kantoor' staan.
const LEEG = {
  notaris_naam: '',
  notaris_standplaats: '',
  kantoor_naam: '',
  bank_volmachthouder: '',
  volmacht_tekst: [],
  slot_tekst: [],
  btw_percentage: 21,
  offerte_geldigheidsdagen: 30,
  offerte_slottekst: [],
};

function regels(waarde) {
  if (Array.isArray(waarde)) return waarde.map(String);
  return waarde ? [String(waarde)] : [];
}

function getal(waarde, standaard) {
  const n = Number(waarde);
  return Number.isFinite(n) && n >= 0 ? n : standaard;
}

let kantoor = {};
try {
  kantoor = JSON.parse(fs.readFileSync(KANTOOR_PATH, 'utf8'));
} catch (err) {
  // Bestand ontbreekt of onleesbaar: lege defaults teruggeven i.p.v. falen.
  return [{ json: { success: true, exists: false, kantoor: LEEG } }];
}

return [{ json: {
  success: true,
  exists: true,
  kantoor: {
    notaris_naam: String(kantoor.notaris_naam || ''),
    notaris_standplaats: String(kantoor.notaris_standplaats || ''),
    kantoor_naam: String(kantoor.kantoor_naam || ''),
    bank_volmachthouder: String(kantoor.bank_volmachthouder || ''),
    volmacht_tekst: regels(kantoor.volmacht_tekst),
    slot_tekst: regels(kantoor.slot_tekst),
    btw_percentage: getal(kantoor.btw_percentage, LEEG.btw_percentage),
    offerte_geldigheidsdagen: getal(kantoor.offerte_geldigheidsdagen, LEEG.offerte_geldigheidsdagen),
    offerte_slottekst: regels(kantoor.offerte_slottekst),
  },
} }];

const fs = require('fs');
const KANTOOR_PATH = '/data/shared/kantoor.json';

// Body komt als multipart-form-data of json binnen; het veld 'data' bevat de
// kantoor-config als JSON-string (zo vermijden we een CORS-preflight).
const body = $json.body || $json || {};
let incoming = {};
try {
  incoming = typeof body.data === 'string' ? JSON.parse(body.data)
    : (body.data && typeof body.data === 'object') ? body.data
    : body;
} catch (err) {
  throw new Error('Kon kantoor-instellingen niet parsen: ' + err.message);
}

// Bestaande config als basis behouden (schema_version, $comment).
let current = {};
try { current = JSON.parse(fs.readFileSync(KANTOOR_PATH, 'utf8')); } catch (_) {}

function regels(waarde) {
  let lijst = waarde;
  if (typeof lijst === 'string') lijst = lijst.split('\n');
  if (!Array.isArray(lijst)) lijst = [];
  return lijst.map((s) => String(s)).filter((s) => s.trim() !== '');
}

// Zie de waarschuwing in 'Read Kantoor': elk nieuw veld hoort in beide nodes.
const btw = Number(incoming.btw_percentage);
const dagen = Number(incoming.offerte_geldigheidsdagen);

const out = Object.assign({}, current, {
  schema_version: 3,
  notaris_naam: String(incoming.notaris_naam || '').trim(),
  notaris_standplaats: String(incoming.notaris_standplaats || '').trim(),
  // kantoor_naam en volmacht_tekst hebben (nog) geen veld in het
  // instellingenscherm. Stuurt de webapp ze niet mee, dan behouden we de
  // bestaande waarde in plaats van hem leeg te maken.
  kantoor_naam: incoming.kantoor_naam !== undefined
    ? String(incoming.kantoor_naam || '').trim()
    : String(current.kantoor_naam || ''),
  bank_volmachthouder: String(incoming.bank_volmachthouder || '').trim(),
  volmacht_tekst: incoming.volmacht_tekst !== undefined
    ? regels(incoming.volmacht_tekst)
    : (Array.isArray(current.volmacht_tekst) ? current.volmacht_tekst : []),
  slot_tekst: regels(incoming.slot_tekst),
  // Een onzinnig percentage of aantal dagen laat de bestaande waarde staan;
  // een offerte met 0% btw of een aanbod dat gisteren verliep is erger dan een
  // wijziging die niet doorkomt.
  btw_percentage: Number.isFinite(btw) && btw >= 0 && btw <= 100
    ? btw
    : (current.btw_percentage ?? 21),
  offerte_geldigheidsdagen: Number.isFinite(dagen) && dagen >= 1 && dagen <= 365
    ? Math.round(dagen)
    : (current.offerte_geldigheidsdagen ?? 30),
  offerte_slottekst: regels(incoming.offerte_slottekst),
});

try {
  fs.writeFileSync(KANTOOR_PATH, JSON.stringify(out, null, 2) + '\n', 'utf8');
} catch (err) {
  throw new Error('Kon kantoor.json niet schrijven: ' + err.message);
}

return [{ json: { success: true, kantoor: {
  notaris_naam: out.notaris_naam,
  notaris_standplaats: out.notaris_standplaats,
  kantoor_naam: out.kantoor_naam,
  bank_volmachthouder: out.bank_volmachthouder,
  volmacht_tekst: out.volmacht_tekst,
  slot_tekst: out.slot_tekst,
  btw_percentage: out.btw_percentage,
  offerte_geldigheidsdagen: out.offerte_geldigheidsdagen,
  offerte_slottekst: out.offerte_slottekst,
} } }];
